/// <summary>
/// Manages agent tasks and message routing.
/// <para>
/// Event-driven: agents execute on Start and on each incoming NetworkMsg.
/// Termination is external — the caller calls Shutdown() when done.
/// </para>
/// <remarks>
/// CONCURRENCY MODEL (Option C ratified, Gabi 2026-05-21, commit 12a468f5):
/// Each agent is a single <c>Task.Run</c> consuming a per-agent
/// <c>Channel.CreateUnbounded&lt;IsolateMessage&gt;</c> via
/// <c>await foreach (var msg in reader.ReadAllAsync())</c>.
/// The main-side consumer is also a single <c>Task.Run</c> with
/// <c>await foreach</c> on <c>_mainPort.Reader</c>.
/// No locks, no ConcurrentDictionary — single-owning-context invariant.
/// </remarks>
/// </summary>
public class IsolateManager
{
    /// <summary>
    /// Per-agent channel writers: agentId to writer for that agent's channel.
    /// Built up as each agent reports Ready.
    /// </summary>
    private readonly Dictionary<string, ChannelWriter<IsolateMessage>> _agentPorts = new();

    /// <summary>
    /// Main-port channel: all agent to manager messages land here.
    /// Dart <c>ReceivePort _mainPort = ReceivePort()</c> maps to
    /// <c>Channel.CreateUnbounded&lt;IsolateMessage&gt;()</c> (Option C).
    /// </summary>
    private readonly Channel<IsolateMessage> _mainPort = Channel.CreateUnbounded<IsolateMessage>();

    /// <summary>Trace configuration (set via Boot).</summary>
    private TraceConfig _traceConfig = TraceConfig.Off;

    /// <summary>Callback for UI output from agents (for Flutter integration).</summary>
    public Action<string, Term>? OnUIOutput;

    /// <summary>
    /// Infrastructure log: only prints when MAD tracing is on.
    /// Dart <c>print(...)</c> maps to <c>Console.WriteLine(...)</c> (unconditional stdout writer).
    /// </summary>
    private void _Log(string msg)
    {
        if (_traceConfig.Mad) Console.WriteLine($"[IsolateManager] {msg}");
    }

    /// <summary>
    /// Boot all agents from configuration.
    /// Returns when all agents are ready (but not yet started).
    /// <para>
    /// LOAD-BEARING ORDERING: the main-port consumer is started BEFORE any agent task
    /// is spawned (identical to Dart's listener-install-before-spawn discipline — prevents
    /// losing the first Ready message).
    /// </para>
    /// </summary>
    public async Task Boot(BootConfig config, TraceConfig? traceConfig = null)
    {
        _traceConfig = traceConfig ?? TraceConfig.Off;

        var readyTcs = new TaskCompletionSource();
        var readyCount = 0;
        var expectedCount = config.Directives.Count;

        // Start the single main-port consumer BEFORE spawning any agent.
        // The consumer both: (a) increments readyCount for boot completion,
        // AND (b) forwards every message to _HandleMessage.
        // IDEMPOTENT DOUBLE-WRITE: _agentPorts[ready.AgentId] is written here AND
        // inside _HandleMessage's Ready branch (same key, same value). Do NOT optimise away.
        _ = Task.Run(async () =>
        {
            await foreach (var msg in _mainPort.Reader.ReadAllAsync())
            {
                if (msg is Ready ready && !readyTcs.Task.IsCompleted)
                {
                    _agentPorts[ready.AgentId] = ready.SendPort;
                    readyCount++;
                    if (readyCount == expectedCount)
                        readyTcs.SetResult();
                }
                _HandleMessage(msg);
            }
        });

        // Spawn one agent task per directive.
        foreach (var directive in config.Directives)
        {
            var agentChannel = Channel.CreateUnbounded<IsolateMessage>();

            var agentConfig = new AgentConfig(
                agentId: directive.AgentId,
                goalFunctor: directive.GoalFunctor,
                programSource: config.Source,
                rootSelfGlpPath: config.RootSelfGlpPath,
                mainPort: _mainPort.Writer,
                goalArity: (int)directive.GoalArity,
                goalConstantArgs: directive.ConstantArgs,
                sharedSources: config.SharedSources,
                projectDir: config.ProjectDir,
                traceConfig: _traceConfig
            );

            // Fire-and-forget: Dart's await Isolate.spawn() ensures the spawn syscall
            // completed; Task.Run is the non-blocking C# counterpart (Option C).
            _ = Task.Run(() => _AgentIsolateEntry(agentConfig, agentChannel.Reader, agentChannel.Writer));
        }

        // Wait for all agents to report Ready.
        await readyTcs.Task;
    }

    /// <summary>
    /// Start all agents.
    /// <para>Synchronous: Dart <c>port.send(Start())</c> maps to <c>writer.TryWrite(new Start())</c>
    /// (fire-and-forget on unbounded channel — always succeeds).
    /// Fresh <c>new Start()</c> per iteration (Dart allocates per-iteration).</para>
    /// </summary>
    public void Start()
    {
        foreach (var writer in _agentPorts.Values)
        {
            writer.TryWrite(new Start());
        }
    }

    /// <summary>
    /// Inject a UI event to an agent (for testing).
    /// <para>
    /// Unknown-agent path: prints WARNING and returns silently (NOT throw — preserves
    /// Dart's explicit no-throw warning+return contract for this test-helper entry point).
    /// Fresh <c>new PayloadSerializer(agentId)</c> per call (NOT cached — intentional per Dart source).
    /// </para>
    /// </summary>
    public void InjectUIEvent(string agentId, Term message)
    {
        if (!_agentPorts.TryGetValue(agentId, out var writer))
        {
            Console.WriteLine($"[IsolateManager] WARNING: Unknown agent {agentId}");
            return;
        }

        var serializer = new PayloadSerializer(agentId);
        var payload = serializer.SerializeAgentMessage(message);
        writer.TryWrite(new UIEvent(agentId, payload));
    }

    /// <summary>
    /// Shutdown all agent channels.
    /// <para>
    /// Dart <c>_mainPort.close()</c> maps to <c>_mainPort.Writer.Complete()</c>
    /// (signals the <c>await foreach</c> consumer to drain and exit).
    /// CRITICAL: does NOT kill agent tasks (Dart: "Termination is external").
    /// No Thread.Abort, no cancellation — not in the Dart source.
    /// </para>
    /// </summary>
    public Task Shutdown()
    {
        _mainPort.Writer.Complete();
        _agentPorts.Clear();
        return Task.CompletedTask;
    }

    /// <summary>
    /// Handle messages from agent tasks.
    /// <para>
    /// Dart <c>void _handleMessage(dynamic msg)</c> narrows to <c>IsolateMessage</c>
    /// (the abstract base; Dart <c>dynamic</c> was type-erasure on the cross-isolate boundary
    /// that .NET does not need because the channel is generically parameterised on IsolateMessage).
    /// </para>
    /// </summary>
    private void _HandleMessage(IsolateMessage msg)
    {
        if (msg is Ready ready)
        {
            _Log($"{ready.AgentId} ready");
            _agentPorts[ready.AgentId] = ready.SendPort;
        }
        else if (msg is NetworkMsg netMsg)
        {
            _RouteNetworkMessage(netMsg);
        }
    }

    /// <summary>Route a network message to its destination agent.</summary>
    private void _RouteNetworkMessage(NetworkMsg msg)
    {
        if (_traceConfig.Glp)
        {
            if (_IsTracingAgent(msg.From))
                Console.WriteLine($"[{msg.From}] → msg to {msg.To}: {msg.Type}");
            if (_IsTracingAgent(msg.To))
                Console.WriteLine($"[{msg.To}] ← msg from {msg.From}: {msg.Type}");
        }

        if (!_agentPorts.TryGetValue(msg.To, out var targetWriter))
        {
            Console.WriteLine($"[IsolateManager] WARNING: Unknown destination {msg.To}");
            return;
        }

        targetWriter.TryWrite(msg);
    }

    /// <summary>Check if an agent should be traced.</summary>
    private bool _IsTracingAgent(string agentId)
    {
        if (!_traceConfig.Glp && !_traceConfig.Mad) return false;
        if (_traceConfig.Agents != null && !_traceConfig.Agents.Contains(agentId)) return false;
        return true;
    }

    // ── Agent task entry point ────────────────────────────────────────────────

    /// <summary>
    /// Agent task entry point.
    /// <para>
    /// Dart <c>void _agentIsolateEntry(AgentConfig config) async</c> maps to
    /// <c>private static async Task _AgentIsolateEntry(...)</c>.
    /// Three parameters: the config plus the two channel endpoints for this agent's
    /// dedicated channel (reader for receiving, writer for handing back via Ready).
    /// </para>
    /// <remarks>
    /// FATAL-HANG CONTRACT (load-bearing): if the goal label is not found, print an error
    /// and return WITHOUT signalling Ready. This deliberately hangs the boot-side
    /// <c>await readyTcs.Task</c> — the documented fatal-boot signal.
    /// Do NOT add a fallback Ready signal in the error path.
    /// </remarks>
    /// </summary>
    private static async Task _AgentIsolateEntry(
        AgentConfig config,
        ChannelReader<IsolateMessage> selfReader,
        ChannelWriter<IsolateMessage> selfWriter)
    {
        // Step 1: local helpers.
        var agentId = config.AgentId;
        var tc = config.TraceConfig;
        void Log(string m) { if (tc.Mad) Console.WriteLine($"[{agentId}] {m}"); }

        Log("Starting isolate");

        // Step 2: Create GlpEngine — the ONE way to run GLP programs.
        // Non-strict types: actor code may have type warnings that shouldn't be fatal.
        var engine = new GlpEngine(config.RootSelfGlpPath) { StrictTypes = false };

        // Step 3: Enable madGLP mode (loads madPredicates + creates MadContext).
        engine.EnableMadGlp(agentId: agentId);

        // Step 4: Load program code — project-linking mode or legacy sequential mode.
        if (config.ProjectDir != null)
        {
            engine.LoadProject(config.ProjectDir);
            engine.LoadSource(config.ProgramSource, filename: "program");
            Log($"Program loaded via project linking ({config.ProjectDir}) + boot source");
        }
        else
        {
            if (config.SharedSources != null)
            {
                for (var i = 0; i < config.SharedSources.Count; i++)
                    engine.LoadSource(config.SharedSources[i], filename: $"shared_{i}");
            }
            engine.LoadSource(config.ProgramSource, filename: "program");
            Log("Program loaded via GlpEngine (stdlib + madPredicates + user code)");
        }

        // Step 5: Wire trace flag and grab context references.
        engine.DebugTrace = tc.Glp;
        var ctx = engine.MadContext!;
        var runtime = engine.Runtime;

        // Step 6: Initialize permanent index-0 serializer entry for network input.
        // Spec Section 4.1: "At boot time, each agent p creates a permanent entry
        // at index 0 mapping _r(p, 0) to the local writer N_p for p's network input stream."
        var (netInWriter, netInReader) = runtime.Heap.AllocateVariable();
        ctx.Wp.InitializeSerializerEntry(netInWriter);
        Log($"Serializer entry initialized at index 0, netIn=({netInWriter},{netInReader})");

        // Step 7: Wire message routing callback to main port.
        ctx.OnMessageReady = (dest, msg) =>
        {
            Log($"Sending {msg.Type} to {dest}");
            config.MainPort.TryWrite(new NetworkMsg(agentId, dest, msg.Payload, msg.Type));
        };
        Log($"Network input ready: writer={netInWriter}, reader={netInReader}");

        // Step 8: Find goal entry point — FATAL if not found (no Ready signal; hangs boot).
        var program = engine.CombinedProgram;
        var arity = config.GoalArity;
        var goalLabel = $"{config.GoalFunctor}/{arity}";
        if (!program.Labels.TryGetValue(goalLabel, out var goalPC))
        {
            Console.WriteLine($"[{agentId}] ERROR: Goal {goalLabel} not found");
            return; // Deliberately NO Ready signal — fatal-hang boot contract preserved.
        }

        // Step 9: Build argument map.
        // arg 0 = agent ID (constant), args 1..n-2 = constant args, arg n-1 = netIn reader.
        var args = new Dictionary<int, Term>();

        // Arg 0: agent ID (constant).
        var (idArgWriter, idArgReader) = runtime.Heap.AllocateVariable();
        runtime.Heap.BindVariable(idArgWriter, new ConstTerm(agentId));
        args[0] = new VarRef(idArgReader);

        // Args 1..n-2: additional constant args from boot directive.
        for (var i = 0; i < config.GoalConstantArgs.Count; i++)
        {
            var constVal = config.GoalConstantArgs[i];
            var (cw, cr) = runtime.Heap.AllocateVariable();
            if (int.TryParse(constVal, out var intVal))
                runtime.Heap.BindVariable(cw, new ConstTerm(intVal));
            else
                runtime.Heap.BindVariable(cw, new ConstTerm(constVal));
            args[i + 1] = new VarRef(cr);
        }

        // Last arg: network input reader.
        var (netInArgWriter, netInArgReader) = runtime.Heap.AllocateVariable();
        runtime.Heap.BindVariable(netInArgWriter, new VarRef(netInReader));
        args[arity - 1] = new VarRef(netInArgReader);

        // Step 10: Spawn main goal.
        runtime.SetGoalEnv(1, new CallEnv(args: args));
        runtime.SetGoalProgram(1, "main");
        runtime.Gq.Enqueue(new GoalRef(1, goalPC));
        Log($"Spawned {config.GoalFunctor}/{arity}");

        // Step 11: Create scheduler and wire trace sinks.
        var runner = new BytecodeRunner(program);
        var scheduler = new Scheduler(
            rt: runtime,
            runners: new Dictionary<object?, BytecodeRunner> { ["main"] = runner });

        if (tc.Glp)
            scheduler.TraceSink = (string line) => Console.WriteLine($"[{agentId}] {line}");

        if (tc.Mad)
            ctx.TraceSink = (string line) => Console.WriteLine(line);

        // Step 12: Signal ready — hand our own channel writer back to the manager.
        // Dart: config.mainPort.send(Ready(agentId, receivePort.sendPort))
        // C#:   config.MainPort.TryWrite(new Ready(agentId, selfWriter))
        config.MainPort.TryWrite(new Ready(agentId, selfWriter));

        // Step 13: Event-driven message handling loop.
        // Dart: await for (final msg in receivePort) { ... }
        // C#:   await foreach (var msg in selfReader.ReadAllAsync()) { ... }
        await foreach (var msg in selfReader.ReadAllAsync())
        {
            if (msg is Start)
            {
                // Initial drain+flush: kicks off the agent's goal.
                scheduler.DrainWithStatus(debug: engine.DebugTrace);
                ctx.FlushMessages();
            }
            else if (msg is NetworkMsg netMsg)
            {
                Log($"Received {netMsg.Type} from {netMsg.From}");

                if (netMsg.Type == MessageType.Assignment)
                {
                    var serializer = new PayloadSerializer(agentId);
                    try
                    {
                        // Convert IReadOnlyList<byte> to byte[] for the deserializer.
                        var payloadBytes = netMsg.Payload as byte[]
                            ?? new List<byte>(netMsg.Payload).ToArray();

                        var (globalName, value) = serializer.DeserializeGlobalSendPayload(
                            payloadBytes,
                            (isReader) =>
                            {
                                var (w, r) = runtime.Heap.AllocateVariable();
                                return isReader ? r : w;
                            });

                        Log($"Assignment: {globalName} := {value}");

                        ctx.HandleMadAssignment(
                            globalName: globalName,
                            value: value,
                            fromAgent: netMsg.From);
                    }
                    catch (Exception e)
                    {
                        Console.WriteLine($"[{agentId}] ERROR handling assignment: {e}");
                    }
                }
                else if (netMsg.Type == MessageType.AgentMessage)
                {
                    Log($"Received agent message from {netMsg.From}");
                }

                // Drain activated goals and flush any response messages.
                scheduler.DrainWithStatus(debug: engine.DebugTrace);
                ctx.FlushMessages();
            }
            else if (msg is UIEvent)
            {
                // UIEvent handling is for external Flutter UI integration.
                // With the current architecture (actors internal to GLP), this is not used.
                Log("Received UI event (not processed - actors are internal)");
            }
        }
    }
}
